// Generated by `bun run gen:client` in the Sora repository. Do not edit by hand.
// Runtime for the Sora client: one function, `callSora`, used by every generated tool function.

export interface SoraRoute {
  method: string;
  path: string;
}

export interface SoraCallOptions {
  /** Defaults to env SORA_URL, then http://127.0.0.1:3016. */
  baseUrl?: string;
  /** Defaults to env SORA_API_KEY (sent as a Bearer token). */
  apiKey?: string;
  timeoutMs?: number;
  /** Test seam. */
  fetch?: typeof fetch;
}

/** Error returned by Sora (the REST error body) or raised locally (timeout, network). */
export class SoraError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: number,
    readonly retryable: boolean,
    readonly details?: unknown,
  ) {
    super(message);
    this.name = 'SoraError';
  }
}

const env = (name: string): string | undefined => (globalThis as { process?: { env: Record<string, string | undefined> } }).process?.env[name];

/**
 * Calls one Sora REST route. `:name` segments of the path are filled from `input`;
 * the remaining fields become the JSON body (POST) or the query string (GET/DELETE).
 */
export async function callSora<T>(route: SoraRoute, input: Record<string, unknown> = {}, options: SoraCallOptions = {}): Promise<T> {
  const rest = { ...input };
  const path = route.path.replace(/:(\w+)/g, (_, name: string) => {
    const value = rest[name];
    delete rest[name];
    return encodeURIComponent(String(value));
  });
  const base = (options.baseUrl ?? env('SORA_URL') ?? 'http://127.0.0.1:3016').replace(/\/+$/, '');
  const headers: Record<string, string> = { Accept: 'application/json' };
  const apiKey = options.apiKey ?? env('SORA_API_KEY');
  if (apiKey) headers.Authorization = `Bearer ${apiKey}`;

  let url = base + path;
  let body: string | undefined;
  if (route.method === 'POST') {
    headers['Content-Type'] = 'application/json';
    body = JSON.stringify(rest);
  } else {
    const query = new URLSearchParams();
    for (const [key, value] of Object.entries(rest)) {
      if (value === undefined || value === null) continue;
      query.set(key, typeof value === 'object' ? JSON.stringify(value) : String(value));
    }
    if ([...query].length > 0) url += `?${query}`;
  }

  let response: Response;
  try {
    response = await (options.fetch ?? fetch)(url, { method: route.method, headers, body, signal: AbortSignal.timeout(options.timeoutMs ?? 120_000) });
  } catch (error) {
    const timedOut = error instanceof Error && (error.name === 'TimeoutError' || error.name === 'AbortError');
    throw new SoraError(error instanceof Error ? error.message : String(error), timedOut ? 'TIMEOUT' : 'NETWORK_ERROR', 0, true);
  }

  const text = await response.text();
  let json: unknown;
  try {
    json = text ? JSON.parse(text) : undefined;
  } catch {
    json = undefined;
  }
  if (!response.ok) {
    const e = (json ?? {}) as { error?: string; code?: string; retryable?: boolean; details?: unknown };
    throw new SoraError(e.error ?? (text.slice(0, 200) || response.statusText), e.code ?? 'HTTP_ERROR', response.status, e.retryable ?? response.status >= 500, e.details);
  }
  return json as T;
}
